VoiceSlot_SaveState:
	pushw wa
	push xhl
	push xiz
	push xiy
	and a, 0x7
	sla a, 3
	xor w, w
	exts xwa
	add xwa, 0xDFF
	ld xhl, xwa
	call VoiceSlot_ComputeWordIndex
	ld xiy, 0xC9E
	ld_sriw3 WA, 0x07, 0xF4, 0xF8
	ld (xhl), wa
	srl iz, 1
	ldfr_lerp XIY, 0x38
	st_dri3b E, 0x07, 0xF4, 0xF8
	ld a, (xiy + 32)
	ldto_lerp XIY, 0x38
	ld (xhl + 2), a
	ldda8 a, 3415
	ld (xhl + 3), a
	ldda16 xwa, 3416
	ld (xhl + 4), wa
	ldda16 xwa, 3418
	ld (xhl + 6), wa
	pop xiy
	pop xiz
	pop xhl
	popw wa
	ret

VoiceSlot_RestoreState:
	pushw wa
	push xhl
	push xiz
	push xiy
	call LABEL_EFD134
	call LABEL_EFD16B
	pop xiy
	pop xiz
	pop xhl
	popw wa
	ret

