	.endif
	ld (xbc), xwa
	lda_24 xwa, \ParamB
	ld (xbc + 4), xwa
	ldw (xbc + 8), \ParamC
	lda_24 xwa, \ParamD
	ld (xbc + 10), xwa
	.if \ParamE <= 7
	lds wa, \ParamE
	.else
	ldw wa, \ParamE
	.endif
	call RegisterObjectTable
.endm


.macro RegMode ParamA, ParamBhi, ParamBlow, ParamC, ParamD, ParamE
	pushw \ParamA
	pushw \ParamBhi
	pushw \ParamBlow
	.if \ParamC <= 7
	lds32 xwa, \ParamC
	.else
	ld xwa, \ParamC
	.endif
	.if \ParamD <= 7
	lds32 xbc, \ParamD
	.else
	ld xbc, \ParamD
	.endif
	.if \ParamE <= 7
	lds32 xde, \ParamE
	.else
	ld xde, \ParamE
	.endif
	call RegisterMode
.endm


.macro RegTitle ParamA, ParamBhi, ParamBlow, ParamC, ParamD, ParamE
	pushw \ParamA
	pushw \ParamBhi
	pushw \ParamBlow
